\begin{frame}{Mutational Variance and Infinitesimal Model}
  \textit{暂无内容。}
  \vspace{0.3cm}
  \begin{itemize}
    \item 增量突变模型：$a^* = a + \alpha$，$\alpha$ 均值为零，方差 $\sigma^2(\alpha_i)$
    \item 每代突变方差 $\sigma_m^2 = 2\sum \mu_i \sigma^2(\alpha_i)$
    \item 无穷小模型下，第 $t$ 代期望加性方差：
    \item 若无初始变异 ($\sigma_A^2(0)=0$)，突变贡献方差趋于 $2N_e\sigma_m^2$（平衡值）
  \end{itemize}
  \[
    \sigma_A^2(t) \simeq 2N_e\sigma_m^2 + \left[\sigma_A^2(0) - 2N_e\sigma_m^2\right] e^{-t/2N_e}
  \]
\end{frame}

\begin{frame}{Asymptotic Rate of Response from Mutations}
  \textit{暂无内容。}
  \vspace{0.3cm}
  \begin{itemize}
    \item 当 $t \gg 2N_e$ 时，每代响应趋近该渐近速率
    \item 达到一半渐近速率所需时间为 $t \simeq 1.4 N_e$ (Hill 1982a,b)
    \item 直观解释：Robertson 理论影响，新突变贡献的最终响应约为 $2N_e$ 倍初始贡献
    \item 无穷小模型假设每个位点选择系数极小，近似中性；此时渐近速率只取决于 $N_e \bar{\imath} \sigma_m^2$
  \end{itemize}
  \[
    r_m(\infty) = 2N_e \bar{\imath} \frac{\sigma_m^2}{\sigma_z}
  \]
\end{frame}

\begin{frame}{Cumulative Mutational Response and Transient Dynamics}
  \textit{暂无内容。}
  \vspace{0.3cm}
  \begin{itemize}
    \item 结合初始变异的累计响应：
    \item 当 $t$ 足够大时，$t\sigma_m^2$ 项主导，响应呈线性
    \item 若起始处于突变-漂变平衡，上述 transient 项为零
  \end{itemize}
  \[
    R_m(t) \simeq 2N_e \bar{\imath} \frac{\sigma_m^2}{\sigma_z} \left( t - 2N_e[1 - e^{-t/2N_e}] \right)
  \]
  \[
    R(t) = 2N_e \frac{\bar{\imath}}{\sigma_z} \left[ t\sigma_m^2 + \left(1 - e^{-t/2N_e}\right) (\sigma_A^2(0) - 2N_e\sigma_m^2) \right]
  \]
\end{frame}

